#!/usr/bin/env python3
"""
Ambient Intelligence Indexer for Local Transcripts
Reads conversation files, extracts entities, builds relationship graph,
and generates Context Packets.
"""

import json
import re
from pathlib import Path
from datetime import datetime
from collections import defaultdict

# Configuration
INPUT_DIR = Path('input_conversations')
OUTPUT_DIR = Path('output')
TARGET_PROJECT = 'Northstar'

# Entity patterns
DATE_PATTERN = re.compile(r'\[(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})\]')
SPEAKER_PATTERN = re.compile(r'\]\s*([^:]+):\s*(.+)')
MARKER_PATTERN = re.compile(r'MARKER:\s*(\S+)')

# Known entities (extracted from context)
PEOPLE = {'Maya', 'Leo', 'Alice', 'Priya', 'Sam'}
ORGANIZATIONS = {'Orion Labs'}
PROJECTS = {'Northstar'}

def read_conversations():
    """Read all conversation files from input directory."""
    conversations = []
    for filepath in sorted(INPUT_DIR.glob('*.txt')):
        content = filepath.read_text()

        # Extract marker
        marker_match = MARKER_PATTERN.search(content)
        marker = marker_match.group(1) if marker_match else None

        # Parse utterances
        utterances = []
        for line in content.strip().split('\n'):
            if line.startswith('MARKER:'):
                continue
            date_match = DATE_PATTERN.search(line)
            speaker_match = SPEAKER_PATTERN.search(line)
            if date_match and speaker_match:
                date_str, time_str = date_match.groups()
                speaker, message = speaker_match.groups()
                utterances.append({
                    'timestamp': f'{date_str}T{time_str}',
                    'date': date_str,
                    'time': time_str,
                    'speaker': speaker.strip(),
                    'message': message.strip()
                })

        conversations.append({
            'file': filepath.name,
            'marker': marker,
            'utterances': utterances,
            'full_text': content.strip()
        })
    return conversations

def extract_entities(conversations):
    """Extract entities from conversations."""
    entities = {
        'people': set(),
        'organizations': set(),
        'projects': set(),
        'dates': set()
    }

    for conv in conversations:
        for utterance in conv['utterances']:
            # Extract date
            entities['dates'].add(utterance['date'])

            # Check for known entities in message
            message = utterance['message']
            for person in PEOPLE:
                if person in message or person == utterance['speaker']:
                    entities['people'].add(person)
            for org in ORGANIZATIONS:
                if org in message:
                    entities['organizations'].add(org)
            for project in PROJECTS:
                if project in message:
                    entities['projects'].add(project)

    return {k: sorted(list(v)) for k, v in entities.items()}

def build_relationship_graph(conversations, entities):
    """Build relationship graph with edge types: works_on, client_of, mentioned_with."""
    edges = []
    edge_set = set()  # For deduplication

    for conv in conversations:
        # Track who is mentioned in each conversation
        mentioned_people = set()
        mentioned_orgs = set()
        mentioned_projects = set()

        for utterance in conv['utterances']:
            speaker = utterance['speaker']
            message = utterance['message']

            # Track speaker
            if speaker in PEOPLE:
                mentioned_people.add(speaker)

            # Extract relationships from message content
            for person in PEOPLE:
                if person in message:
                    mentioned_people.add(person)
            for org in ORGANIZATIONS:
                if org in message:
                    mentioned_orgs.add(org)
            for project in PROJECTS:
                if project in message:
                    mentioned_projects.add(project)

        # Build works_on relationships (people working on projects)
        # Based on "Northstar is owned by Priya and Sam"
        for person in mentioned_people:
            for project in mentioned_projects:
                edge_key = (person, 'works_on', project)
                if edge_key not in edge_set:
                    # Check if there's evidence in the text
                    for utterance in conv['utterances']:
                        if person in utterance['message'] and project in utterance['message']:
                            if 'owned by' in utterance['message'] or 'needs' in utterance['message']:
                                edges.append({
                                    'source': person,
                                    'target': project,
                                    'type': 'works_on',
                                    'evidence': utterance['message'],
                                    'conversation': conv['file'],
                                    'marker': conv['marker']
                                })
                                edge_set.add(edge_key)
                                break

        # Build client_of relationships (organizations that are clients)
        for org in mentioned_orgs:
            for project in mentioned_projects:
                edge_key = (org, 'client_of', project)
                if edge_key not in edge_set:
                    for utterance in conv['utterances']:
                        if org in utterance['message'] and project in utterance['message']:
                            if 'client' in utterance['message'].lower() or 'contract' in utterance['message'].lower():
                                edges.append({
                                    'source': org,
                                    'target': project,
                                    'type': 'client_of',
                                    'evidence': utterance['message'],
                                    'conversation': conv['file'],
                                    'marker': conv['marker']
                                })
                                edge_set.add(edge_key)
                                break

        # Build mentioned_with relationships (co-occurrence in same conversation)
        people_list = sorted(list(mentioned_people))
        for i, p1 in enumerate(people_list):
            for p2 in people_list[i+1:]:
                edge_key = tuple(sorted([p1, p2])) + ('mentioned_with',)
                if edge_key not in edge_set:
                    edges.append({
                        'source': p1,
                        'target': p2,
                        'type': 'mentioned_with',
                        'evidence': f'Both mentioned in {conv["file"]}',
                        'conversation': conv['file'],
                        'marker': conv['marker']
                    })
                    edge_set.add(edge_key)

    return edges

def extract_relevant_snippets(conversations, topic_keywords):
    """Extract conversation snippets relevant to given topics."""
    snippets = []

    for conv in conversations:
        for utterance in conv['utterances']:
            message_lower = utterance['message'].lower()
            for keyword in topic_keywords:
                if keyword.lower() in message_lower:
                    snippets.append({
                        'conversation': conv['file'],
                        'marker': conv['marker'],
                        'timestamp': utterance['timestamp'],
                        'speaker': utterance['speaker'],
                        'message': utterance['message'],
                        'relevance': keyword
                    })
                    break  # One match per utterance

    return snippets

def generate_context_packet(conversations, entities, relationships, target_project):
    """Generate Context Packet for the specified project."""
    # Find most recent conversations about deadline shift and client onboarding
    deadline_snippets = extract_relevant_snippets(conversations, ['deadline', 'timeline', 'kickoff', 'moved'])
    onboarding_snippets = extract_relevant_snippets(conversations, ['onboarding', 'blocked', 'legal', 'DPA'])

    # Get most recent conversation (last in sorted list)
    most_recent_conv = conversations[-1] if conversations else None

    context_packet = {
        'project': target_project,
        'generated_at': datetime.now().isoformat(),
        'recent_conversations': [
            {
                'file': conv['file'],
                'marker': conv['marker'],
                'date': conv['utterances'][0]['date'] if conv['utterances'] else None,
                'summary': conv['utterances'][-1]['message'] if conv['utterances'] else ''
            }
            for conv in conversations
        ],
        'resolved_entities': {
            'people': entities['people'],
            'organizations': entities['organizations'],
            'projects': entities['projects'],
            'dates': entities['dates']
        },
        'relationships': relationships,
        'relevant_history': {
            'deadline_shift': deadline_snippets,
            'client_onboarding': onboarding_snippets
        },
        'most_recent_context': {
            'conversation': most_recent_conv['file'] if most_recent_conv else None,
            'marker': most_recent_conv['marker'] if most_recent_conv else None,
            'summary': most_recent_conv['full_text'] if most_recent_conv else None
        }
    }

    return context_packet

def generate_searchable_summary(conversations, entities, relationships):
    """Generate a searchable summary file."""
    summary = {
        'index_version': '1.0',
        'generated_at': datetime.now().isoformat(),
        'total_conversations': len(conversations),
        'entities': entities,
        'relationships': relationships,
        'conversation_index': [],
        'searchable_text': ''
    }

    all_text = []
    for conv in conversations:
        conv_entry = {
            'file': conv['file'],
            'marker': conv['marker'],
            'dates': list(set(u['date'] for u in conv['utterances'])),
            'speakers': list(set(u['speaker'] for u in conv['utterances'])),
            'utterances': conv['utterances']
        }
        summary['conversation_index'].append(conv_entry)
        all_text.append(conv['full_text'])

    summary['searchable_text'] = '\n\n'.join(all_text)

    return summary

def main():
    """Main entry point."""
    # Ensure output directory exists
    OUTPUT_DIR.mkdir(exist_ok=True)

    print(f"Reading conversations from {INPUT_DIR}...")
    conversations = read_conversations()
    print(f"Found {len(conversations)} conversation files.")

    print("Extracting entities...")
    entities = extract_entities(conversations)
    print(f"Found {len(entities['people'])} people, {len(entities['organizations'])} organizations, "
          f"{len(entities['projects'])} projects, {len(entities['dates'])} dates.")

    print("Building relationship graph...")
    relationships = build_relationship_graph(conversations, entities)
    print(f"Found {len(relationships)} relationships.")

    print(f"Generating Context Packet for project '{TARGET_PROJECT}'...")
    context_packet = generate_context_packet(conversations, entities, relationships, TARGET_PROJECT)

    print("Generating searchable summary...")
    summary = generate_searchable_summary(conversations, entities, relationships)

    # Write outputs
    context_packet_path = OUTPUT_DIR / f"context_packet_{TARGET_PROJECT}.json"
    with open(context_packet_path, 'w') as f:
        json.dump(context_packet, f, indent=2, sort_keys=True)
    print(f"Written: {context_packet_path}")

    summary_path = OUTPUT_DIR / "searchable_summary.json"
    with open(summary_path, 'w') as f:
        json.dump(summary, f, indent=2, sort_keys=True)
    print(f"Written: {summary_path}")

    # Write relationship graph as separate file
    graph_path = OUTPUT_DIR / "relationship_graph.json"
    with open(graph_path, 'w') as f:
        json.dump({'nodes': entities, 'edges': relationships}, f, indent=2, sort_keys=True)
    print(f"Written: {graph_path}")

    print("\nIndexing complete!")

if __name__ == '__main__':
    main()
