            entities['dates'].add(utterance['date'])
            message = utterance['message']
            for person in PEOPLE:
                if person in message or person == utterance['speaker']:
                    entities['people'].add(person)
            for org in ORGANIZATIONS:
                if org in message:
                    entities['organizations'].add(org)
            for project in PROJECTS:
                if project in message:
                    entities['projects'].add(project)
    return {k: sorted(list(v)) for k, v in entities.items()}

def build_relationship_graph(conversations, entities):
    edges = []
    edge_set = set()
    for conv in conversations:
        mentioned_people = set()
        mentioned_orgs = set()
        mentioned_projects = set()
        for utterance in conv['utterances']:
            speaker = utterance['speaker']
            message = utterance['message']
            if speaker in PEOPLE:
                mentioned_people.add(speaker)
            for person in PEOPLE:
                if person in message:
                    mentioned_people.add(person)
            for org in ORGANIZATIONS:
                if org in message:
                    mentioned_orgs.add(org)
            for project in PROJECTS:
                if project in message:
                    mentioned_projects.add(project)
        for person in mentioned_people:
            for project in mentioned_projects:
                edge_key = (person, 'works_on', project)
                if edge_key not in edge_set:
                    for utterance in conv['utterances']:
                        if person in utterance['message'] and project in utterance['message']:
                            if 'owned by' in utterance['message'] or 'needs' in utterance['message']:
                                edges.append({'source': person, 'target': project, 'type': 'works_on', 'evidence': utterance['message'], 'conversation': conv['file'], 'marker': conv['marker']})
                                edge_set.add(edge_key)
                                break
        for org in mentioned_orgs:
            for project in mentioned_projects:
                edge_key = (org, 'client_of', project)
                if edge_key not in edge_set:
                    for utterance in conv['utterances']:
                        if org in utterance['message'] and project in utterance['message']:
                            if 'client' in utterance['message'].lower() or 'contract' in utterance['message'].lower():
                                edges.append({'source': org, 'target': project, 'type': 'client_of', 'evidence': utterance['message'], 'conversation': conv['file'], 'marker': conv['marker']})
                                edge_set.add(edge_key)
                                break
        people_list = sorted(list(mentioned_people))
        for i, p1 in enumerate(people_list):
            for p2 in people_list[i+1:]:
                edge_key = tuple(sorted([p1, p2])) + ('mentioned_with',)
                if edge_key not in edge_set:
                    edges.append({'source': p1, 'target': p2, 'type': 'mentioned_with', 'evidence': 'Both mentioned in ' + conv['file'], 'conversation': conv['file'], 'marker': conv['marker']})
                    edge_set.add(edge_key)
    return edges

def extract_relevant_snippets(conversations, topic_keywords):
    snippets = []
    for conv in conversations:
        for utterance in conv['utterances']:
            message_lower = utterance['message'].lower()
            for keyword in topic_keywords:
                if keyword.lower() in message_lower:
                    snippets.append({'conversation': conv['file'], 'marker': conv['marker'], 'timestamp': utterance['timestamp'], 'speaker': utterance['speaker'], 'message': utterance['message'], 'relevance': keyword})
                    break
    return snippets

def generate_context_packet(conversations, entities, relationships, target_project):
    deadline_snippets = extract_relevant_snippets(conversations, ['deadline', 'timeline', 'kickoff', 'moved'])
    onboarding_snippets = extract_relevant_snippets(conversations, ['onboarding', 'blocked', 'legal', 'DPA'])
    most_recent_conv = conversations[-1] if conversations else None
    context_packet = {
        'project': target_project,
        'generated_at': datetime.now().isoformat(),
        'recent_conversations': [{'file': conv['file'], 'marker': conv['marker'], 'date': conv['utterances'][0]['date'] if conv['utterances'] else None, 'summary': conv['utterances'][-1]['message'] if conv['utterances'] else ''} for conv in conversations],
        'resolved_entities': {'people': entities['people'], 'organizations': entities['organizations'], 'projects': entities['projects'], 'dates': entities['dates']},
        'relationships': relationships,
        'relevant_history': {'deadline_shift': deadline_snippets, 'client_onboarding': onboarding_snippets},
        'most_recent_context': {'conversation': most_recent_conv['file'] if most_recent_conv else None, 'marker': most_recent_conv['marker'] if most_recent_conv else None, 'summary': most_recent_conv['full_text'] if most_recent_conv else None}
    }
    return context_packet

def generate_searchable_summary(conversations, entities, relationships):
    summary = {'index_version': '1.0', 'generated_at': datetime.now().isoformat(), 'total_conversations': len(conversations), 'entities': entities, 'relationships': relationships, 'conversation_index': [], 'searchable_text': ''}
    all_text = []
    for conv in conversations:
        conv_entry = {'file': conv['file'], 'marker': conv['marker'], 'dates': list(set(u['date'] for u in conv['utterances'])), 'speakers': list(set(u['speaker'] for u in conv['utterances'])), 'utterances': conv['utterances']}
        summary['conversation_index'].append(conv_entry)
        all_text.append(conv['full_text'])
    summary['searchable_text'] = '\n\n'.join(all_text)
    return summary

