                "snippet": most_recent_onboarding["lines"][-1] if most_recent_onboarding and most_recent_onboarding["lines"] else None
            }
        },
        "summary": "Context packet for Northstar project including entity relationships and key conversation references"
    }
    return packet

def generate_searchable_summary(conversations, entities):
    snippets = []
    all_keywords = entities["people"] + entities["organizations"] + entities["projects"]

    for conv in conversations:
        for line in conv["lines"]:
            line_lower = line.lower()
            relevant_keywords = [k for k in all_keywords if k.lower() in line_lower]
            key_topics = ["deadline", "onboarding", "blocked", "client", "northstar", "orion"]
            topic_matches = [t for t in key_topics if t in line_lower]

            if relevant_keywords or topic_matches:
                snippet = {
                    "text": line,
                    "source": conv["source"],
                    "keywords": list(set(relevant_keywords + topic_matches)),
                    "entities_mentioned": relevant_keywords
                }
                snippets.append(snippet)

    return {"total_snippets": len(snippets), "indexed_entities": entities, "snippets": snippets}

def main():
    OUTPUT_DIR.mkdir(exist_ok=True)

    conversations = read_conversations()
    entities = extract_entities(conversations)
    relationships = build_relationships(conversations)
    context_packet = generate_context_packet(conversations, entities, relationships)
    searchable_summary = generate_searchable_summary(conversations, entities)

    with open(OUTPUT_DIR / "context_packet.json", "w") as f:
        json.dump(context_packet, f, indent=2)

    with open(OUTPUT_DIR / "searchable_summary.json", "w") as f:
        json.dump(searchable_summary, f, indent=2)

    with open(OUTPUT_DIR / "relationships.json", "w") as f:
        json.dump(relationships, f, indent=2)

    with open(OUTPUT_DIR / "entities.json", "w") as f:
        json.dump(entities, f, indent=2)

    print("Output files written to ./output/")
    print("Entities found:", sum(len(v) for v in entities.values()))
    print("Relationships extracted:", len(relationships))
    print("Snippets indexed:", len(searchable_summary["snippets"]))

if __name__ == "__main__":
    main()
